input.newString:
// The BSD checksum output is 5 digit integer
let bsd_width = 5;
match (options.algo_name, not_file) {
    (ALGORITHM_OPTIONS_SYSV, true) => println!(
        "{} {}",
        sum.parse::<u16>().unwrap(),
        div_ceil(sz, options.output_bits)
    ),
    (ALGORITHM_OPTIONS_SYSV, false) => print_line_with_filename(
        &format!(
            "{} {} ",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        "",
        filename,
    )?,
    (ALGORITHM_OPTIONS_BSD, true) => println!(
        "{:0bsd_width$} {:bsd_width$}",
        sum.parse::<u16>().unwrap(),
        div_ceil(sz, options.output_bits)
    ),
    (ALGORITHM_OPTIONS_BSD, false) => print_line_with_filename(
        &format!(
            "{:0bsd_width$} {:bsd_width$} ",
            sum.parse::<u16>().unwrap(),
            div_ceil(sz, options.output_bits)
        ),
        "",
        filename,
    )?,
    (ALGORITHM_OPTIONS_CRC, true) => println!("{sum} {sz}"),
    (ALGORITHM_OPTIONS_CRC, false) => {
        print_line_with_filename(&format!("{sum} {sz} "), "", filename)?
    }
    (ALGORITHM_OPTIONS_BLAKE2B, _) if options.tag => {
        let before = if let Some(length) = options.length {
            // Multiply by 8 here, as we want to print the length in bits.
            format!("BLAKE2b-{} (", length * 8)
        } else {
            "BLAKE2b (".to_string()
        };
        print_line_with_filename(&before, &format!(") = {sum}"), filename)?;
    }
    _ => {
        if options.tag {
            print_line_with_filename(
                &format!("{} (", options.algo_name.to_ascii_uppercase()),
                &format!(") = {sum}"),
                filename,
            )?;
        } else {
            let prefix = if options.asterisk { "*" } else { " " };
            print_line_with_filename(&format!("{sum} {prefix}"), "", filename)?;
        }
    }
}

